import React, { useEffect, useRef } from "react";

/* ==========================================================
   CORE FLOW
   ----------------------------------------------------------
   Dotted streams sweep in from both edges of the hero and
   converge on the robot. The robot is fed by them:

   • charge — every particle that lands adds to the core's glow,
     which ebbs back; every fortieth arrival the robot pulses
   • colour — particles leave the edges white and warm into the
     core's gold as they close in, trailing a short comet tail
   • gravity — the streams lean toward the cursor and spring
     back when it leaves; a click still sends a shockwave
   • depth — each stream sits on a near/far layer (brighter and
     thicker when near) and shifts with the pointer
   • signal — every few seconds one bright particle leaves the
     core toward the primary CTA, which answers with a glow
   • exit — scrolling away scatters the particles outward

   Ported from the canvas inside 21st.dev's "Gateway Flow" (the
   iframe, Tailwind, GSAP and demo page around it were dropped).
   One canvas, paused off screen and in hidden tabs.
   ========================================================== */

const PATHS_PER_SIDE = 26;
const EDGE_FADE = 170; // px over which a stream fades in from its start
const LINE_ALPHA = 0.26;
const SEGMENTS = 36; // polyline resolution, so gravity can bend a stream
const GRAVITY_R = 170;
const TAIL = 4;
const SIGNAL_EVERY = 6500;

/* Words that ride the streams into the core, decoding from noise on the
   way in. The stack, as the thing the robot is made of. */
const WORDS = [
  // models & providers
  "LLM", "Gemini", "Claude", "GPT", "Llama", "Hugging Face", "vLLM",
  // retrieval
  "RAG", "Embeddings", "Vector DB", "Rerank", "Chunking", "Hybrid search",
  "Citations", "Grounding", "ChromaDB", "AlloyDB",
  // agents
  "Agents", "MCP", "Tool calls", "Multi-agent", "Planner", "Memory",
  "Guardrails", "Human-in-loop", "LangChain", "LangGraph", "CrewAI",
  // quality & ops
  "Evals", "Tracing", "Prompts", "Fine-tune", "LoRA", "Tokens",
  "Latency", "Caching", "Streaming",
  // platform
  "Python", "FastAPI", "Vertex AI", "Cloud Run", "BigQuery", "Pub/Sub",
  "Docker", "Kubernetes", "React", "TypeScript", "PyTorch",
];
const GLYPHS = "01アイウエオカキクケコサシスセソ<>/{}[]#$%&*+=";
const WORD_EVERY = 4; // one word-carrying pair of streams in every four
// Never the same word twice on screen: 14 in flight, 48 in the pool, so
// there is always a fresh one to hand out.
const TEAL = [77, 182, 172];
const SIGNAL_MS = 1500;

function hexToRgb(hex) {
  const n = parseInt(String(hex).replace("#", ""), 16);
  if (Number.isNaN(n)) return [228, 168, 83];
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

const mixRgb = (a, b, t) => [
  Math.round(a[0] + (b[0] - a[0]) * t),
  Math.round(a[1] + (b[1] - a[1]) * t),
  Math.round(a[2] + (b[2] - a[2]) * t),
];

export default function CoreFlow({ theme }) {
  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    const hero = canvas && canvas.parentElement;
    if (!canvas || !hero) return undefined;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)")
      .matches;
    const light = theme?.name === "light";
    const inkRgb = light ? [26, 31, 42] : [255, 255, 255];
    const ink = inkRgb.join(", ");
    const gold = hexToRgb(theme?.accentColor || "#e4a853");
    const ctx = canvas.getContext("2d");
    const dpr = Math.min(window.devicePixelRatio || 1, 2);

    let W = 0;
    let H = 0;
    let target = null;
    let signalEnd = null;
    let reach = 0;
    let paths = [];
    let explosions = [];
    let raf = 0;
    let running = false;
    let visible = true;
    let born = 0;
    let lastT = 0;

    // Pointer, smoothed: `pull` eases toward 1 while the cursor is in the
    // hero and back to 0 when it leaves, so the streams spring back.
    let mouse = { x: 0, y: 0 };
    let pull = 0;
    let pointerIn = false;
    let par = { x: 0, y: 0 }; // parallax, -1..1, smoothed

    // Core feedback.
    let charge = 0;
    let arrivals = 0;
    let robotEl = null;
    let padEl = null;
    let lastChargeWrite = -1;

    // Outbound signal toward the CTA.
    let signal = null;
    let lastSignal = 0;

    // Words currently in flight, so no term is ever on screen twice (on the
    // same side or mirrored across).
    const inFlight = new Set();
    const pickWord = (rand) => {
      const free = WORDS.filter((x) => !inFlight.has(x));
      const pool = free.length ? free : WORDS;
      const word = pool[Math.floor(rand() * pool.length)];
      inFlight.add(word);
      return word;
    };

    let seed = 11;
    const rnd = () => {
      seed = (seed * 16807) % 2147483647;
      return seed / 2147483647;
    };

    const layout = () => {
      const h = hero.getBoundingClientRect();
      const robot = document.querySelector(".core-robot");
      const copy = hero.querySelector(".hero-valueprop");
      const cta = hero.querySelector(".jarvis-cta");
      if (!robot || !h.width) return false;
      const r = robot.getBoundingClientRect();
      robotEl = robot;
      padEl = document.querySelector(".core-basepad");

      W = h.width;
      H = h.height;
      canvas.width = Math.round(W * dpr);
      canvas.height = Math.round(H * dpr);
      canvas.style.width = `${W}px`;
      canvas.style.height = `${H}px`;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

      target = {
        x: r.left - h.left + r.width / 2,
        y: r.top - h.top + r.height * 0.48,
      };

      // The two sides mirror each other: both start the same distance from
      // the core — as far as the left can reach without running under the
      // copy — and both fade in over the same length.
      const copyRight = copy ? copy.getBoundingClientRect().right - h.left : 0;
      reach = Math.max(target.x - (copyRight + 40), 260);
      const l = target.x - reach;
      const rr = target.x + reach;
      canvas.style.setProperty("--flow-l0", `${l}px`);
      canvas.style.setProperty("--flow-l1", `${l + EDGE_FADE}px`);
      canvas.style.setProperty("--flow-r1", `${rr - EDGE_FADE}px`);
      canvas.style.setProperty("--flow-r0", `${rr}px`);

      // The signal heads for the CTA row and dissolves where the left
      // streams begin; the button itself answers with a glow.
      if (cta) {
        const c = cta.getBoundingClientRect();
        signalEnd = { x: l + 20, y: c.top - h.top + c.height / 2 };
      } else {
        signalEnd = null;
      }

      seed = 11;
      paths = [];
      inFlight.clear();
      const particle = () => ({
        t: rnd(),
        speed: 0.0012 + rnd() * 0.0016,
        scatter: 0.6 + rnd() * 0.8,
      });
      // Mirrored pairs: same height and depth on both sides, so the fan is
      // symmetric; each side still gets its own particles and timing.
      for (let i = 0; i < PATHS_PER_SIDE; i++) {
        const z = rnd(); // 0 = far, 1 = near
        const startY =
          target.y + (i / (PATHS_PER_SIDE - 1) - 0.5) * H * 1.25;
        const carries = i % WORD_EVERY === 1;
        [true, false].forEach((isLeft) =>
          paths.push({
            isLeft,
            z,
            startY,
            particles: [particle(), ...(rnd() < 0.35 ? [particle()] : [])],
            word: carries
              ? {
                  t: rnd(),
                  speed: 0.0008 + rnd() * 0.0006,
                  text: pickWord(rnd),
                  scatter: 0.6 + rnd() * 0.8,
                }
              : null,
          })
        );
      }
      return true;
    };

    const bez = (t, p0, p1, p2, p3) => {
      const u = 1 - t;
      return {
        x:
          u * u * u * p0.x + 3 * u * u * t * p1.x + 3 * u * t * t * p2.x +
          t * t * t * p3.x,
        y:
          u * u * u * p0.y + 3 * u * u * t * p1.y + 3 * u * t * t * p2.y +
          t * t * t * p3.y,
      };
    };

    // Lean toward the cursor. Pinned at both ends (t*(1-t)) so a stream
    // still starts at the edge and still lands in the core.
    const bend = (pt, t) => {
      if (pull < 0.01) return pt;
      const dx = mouse.x - pt.x;
      const dy = mouse.y - pt.y;
      const d = Math.hypot(dx, dy);
      if (d > GRAVITY_R || d < 1) return pt;
      const k = (1 - d / GRAVITY_R) ** 2 * 0.42 * pull * (4 * t * (1 - t));
      return { x: pt.x + dx * k, y: pt.y + dy * k };
    };

    const curveOf = (path) => {
      const edge = path.isLeft ? target.x - reach : target.x + reach;
      const run = target.x - edge;
      // Near streams move more with the pointer than far ones.
      const sx = par.x * 16 * path.z;
      const sy = par.y * 22 * path.z;
      return [
        { x: edge + sx, y: path.startY + sy },
        { x: edge + run * 0.5 + sx * 0.6, y: path.startY + sy * 0.6 },
        { x: edge + run * 0.8, y: target.y },
        target,
      ];
    };

    const shockAt = (x, y) => {
      let dx = 0;
      let dy = 0;
      explosions.forEach((e) => {
        const ex = x - e.x;
        const ey = y - e.y;
        const dist = Math.hypot(ex, ey) || 1;
        if (dist < e.radius + 120 && dist > e.radius - 120) {
          const force = (1 - Math.abs(dist - e.radius) / 120) * e.life;
          dx += (ex / dist) * force * 80;
          dy += (ey / dist) * force * 80;
        }
      });
      return { dx, dy };
    };

    const flashCta = () => {
      const cta = hero.querySelector(".jarvis-cta");
      if (!cta || !cta.animate) return;
      const [r, g, b] = gold;
      cta.animate(
        [
          { boxShadow: `0 0 0 0 rgba(${r},${g},${b},0)` },
          {
            boxShadow: `0 0 0 5px rgba(${r},${g},${b},0.22), 0 0 34px rgba(${r},${g},${b},0.45)`,
          },
          { boxShadow: `0 0 0 10px rgba(${r},${g},${b},0)` },
        ],
        { duration: 1100, easing: "ease-out" }
      );
    };

    const pulseCore = () => {
      const wrap = document.querySelector(".core-robot-wrap");
      if (wrap && wrap.animate) {
        wrap.animate([{ scale: "1" }, { scale: "1.022" }, { scale: "1" }], {
          duration: 420,
          easing: "cubic-bezier(0.3, 1.6, 0.5, 1)",
        });
      }
    };

    const writeCharge = () => {
      // Written straight onto the two elements that use it — a custom
      // property on a parent would restyle the robot's whole SVG subtree
      // every frame.
      if (Math.abs(charge - lastChargeWrite) < 0.01) return;
      lastChargeWrite = charge;
      if (robotEl) {
        robotEl.style.filter = `drop-shadow(0 0 ${Math.round(
          30 + charge * 44
        )}px var(--core-accent)) brightness(${(1 + charge * 0.1).toFixed(3)})`;
      }
      if (padEl) padEl.style.opacity = (0.75 + charge * 0.5).toFixed(3);
    };

    /* A word in flight: scrambled glyphs that resolve left to right over the
       first half of the trip, teal while it decodes, warming to gold.
       Everything about its approach is tied to its distance from the core:
       it shrinks like it is receding, its letters close up, and it fades
       out right at the robot's edge. It is also pulled in faster the
       closer it gets. */
    const drawWord = (path, w, curve, now, dt, fade, exit) => {
      if (!reduced) {
        // Gravity well: up to ~2.6x speed on the final approach.
        w.t += w.speed * (dt / 16) * (1 + w.t * w.t * 1.6);
        if (w.t > 1) {
          w.t = 0;
          inFlight.delete(w.text);
          w.text = pickWord(Math.random);
          if (exit < 0.5) charge = Math.min(1, charge + 0.06);
        }
      }
      const t = reduced ? 0.55 : w.t;
      const [p0, p1, p2, p3] = curve;
      let pos = bend(bez(t, p0, p1, p2, p3), t);
      // 1 at the edge of the fan, 0 at the core.
      const near = Math.min(
        1,
        Math.hypot(pos.x - target.x, pos.y - target.y) / (reach || 1)
      );
      const sh = shockAt(pos.x, pos.y);
      pos = {
        x: pos.x + sh.dx + (pos.x - target.x) * exit * w.scatter,
        y: pos.y + sh.dy + (pos.y - target.y) * exit * w.scatter,
      };

      const decoded = Math.min(1, Math.max(0, (t - 0.08) / 0.42));
      const shown = Math.floor(decoded * w.text.length);
      let label = w.text.slice(0, shown);
      // Unresolved characters flicker, slowing as the word resolves.
      const tick = Math.floor(now / (60 + decoded * 140));
      for (let c = shown; c < w.text.length; c++) {
        const ch = w.text[c];
        label +=
          ch === " "
            ? " "
            : GLYPHS[(tick * 7 + c * 13 + w.text.length) % GLYPHS.length];
      }

      const inA = Math.min(1, t / 0.12);
      // Gone by the time it is a fifth of the way from the robot's centre —
      // about where the robot's body starts to cover it.
      const outA = Math.min(1, Math.max(0, (near - 0.18) / 0.22));
      // Continuous perspective shrink: full size at the rim, ~28% at the core.
      const scale = 0.28 + 0.72 * Math.pow(near, 0.85);
      const size = (12 + path.z * 3) * scale;
      const warm = Math.min(1, Math.max(0, (t - 0.45) / 0.45));
      const base = light ? inkRgb : TEAL;
      const [r, g, b] = mixRgb(base, gold, warm);
      const a = (0.35 + decoded * 0.5) * (0.65 + path.z * 0.35) * inA * outA * fade;
      if (a < 0.02) return;

      ctx.font = `600 ${size.toFixed(1)}px ui-monospace, "SF Mono", Menlo, Consolas, monospace`;
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      // Letters close up as the word is drawn in (Chrome/Safari support
      // canvas letterSpacing; elsewhere this is simply ignored).
      if ("letterSpacing" in ctx) {
        ctx.letterSpacing = `${(near * 1.6).toFixed(2)}px`;
      }
      // Soft focus while scrambled, sharp once decoded.
      const blur = (1 - decoded) * 1.1;
      if (blur > 0.05 && "filter" in ctx) ctx.filter = `blur(${blur.toFixed(2)}px)`;
      if (!light && decoded > 0.99) {
        ctx.shadowColor = `rgba(${r}, ${g}, ${b}, ${0.6 * a})`;
        ctx.shadowBlur = 8;
      }
      ctx.fillStyle = `rgba(${r}, ${g}, ${b}, ${a})`;
      ctx.fillText(label, pos.x, pos.y);
      ctx.shadowBlur = 0;
      if ("filter" in ctx) ctx.filter = "none";
      if ("letterSpacing" in ctx) ctx.letterSpacing = "0px";
    };

    const render = (now) => {
      const dt = lastT ? Math.min(now - lastT, 50) : 16;
      lastT = now;
      ctx.clearRect(0, 0, W, H);
      if (!target) return;

      const intro = reduced
        ? 1
        : Math.min(Math.max((now - born - 700) / 1600, 0), 1);

      // Scroll exit: 0 at rest, 1 once the hero is well off the top.
      const top = hero.getBoundingClientRect().top;
      const exit = Math.min(Math.max(-top / (H * 0.6), 0), 1);
      const fade = intro * (1 - exit);

      // Ease the pointer terms.
      const ease = 1 - Math.exp(-dt / 180);
      pull += ((pointerIn ? 1 : 0) - pull) * ease;
      const tx = pointerIn ? (mouse.x / W - 0.5) * 2 : 0;
      const ty = pointerIn ? (mouse.y / H - 0.5) * 2 : 0;
      par.x += (tx - par.x) * ease * 0.5;
      par.y += (ty - par.y) * ease * 0.5;

      explosions.forEach((e) => {
        e.radius += 15;
        e.life -= 0.015;
      });
      explosions = explosions.filter((e) => e.life > 0);

      paths.forEach((path) => {
        const [p0, p1, p2, p3] = curveOf(path);

        // The stream: a bent polyline, dotted, weighted by depth.
        ctx.beginPath();
        for (let s = 0; s <= SEGMENTS; s++) {
          const t = s / SEGMENTS;
          const pt = bend(bez(t, p0, p1, p2, p3), t);
          if (s === 0) ctx.moveTo(pt.x, pt.y);
          else ctx.lineTo(pt.x, pt.y);
        }
        ctx.lineWidth = 0.8 + path.z * 0.8;
        ctx.strokeStyle = `rgba(${ink}, ${
          LINE_ALPHA * (0.45 + path.z * 0.75) * fade
        })`;
        ctx.setLineDash([1, 4]);
        ctx.stroke();
        ctx.setLineDash([]);

        const size = 2 + path.z * 1.6;

        path.particles.forEach((p) => {
          if (!reduced) {
            p.t += p.speed * (dt / 16) * (1 + p.t * p.t * 1.2);
            if (p.t > 1) {
              p.t = 0;
              if (exit < 0.5) {
                charge = Math.min(1, charge + 0.04);
                if (++arrivals % 40 === 0) pulseCore();
              }
            }
          }

          // Head plus a short fading tail, each point on the same curve.
          for (let k = TAIL; k >= 0; k--) {
            const tt = Math.max(0, p.t - k * p.speed * 3.2);
            let pos = bend(bez(tt, p0, p1, p2, p3), tt);
            const sh = shockAt(pos.x, pos.y);
            // Exit: blown outward from the core.
            const ox = (pos.x - target.x) * exit * p.scatter;
            const oy = (pos.y - target.y) * exit * p.scatter;
            pos = { x: pos.x + sh.dx + ox, y: pos.y + sh.dy + oy };

            const warm = Math.min(1, Math.max(0, (tt - 0.35) / 0.6));
            const [r, g, b] = mixRgb(inkRgb, gold, warm);
            const head = k === 0;
            const a =
              (head ? 0.5 + tt * 0.45 : (0.35 * (TAIL - k + 1)) / (TAIL + 1)) *
              (0.6 + path.z * 0.4) *
              fade;
            // Dots recede too: smaller the nearer they are to the core.
            const near = Math.min(
              1,
              Math.hypot(pos.x - target.x, pos.y - target.y) / (reach || 1)
            );
            const depth = 0.4 + 0.6 * near;
            const s = (head ? size : size * (1 - k / (TAIL + 2))) * depth;
            ctx.fillStyle = `rgba(${r}, ${g}, ${b}, ${a})`;
            ctx.fillRect(pos.x - s / 2, pos.y - s / 2, s, s);
          }
        });

        if (path.word) drawWord(path, path.word, [p0, p1, p2, p3], now, dt, fade, exit);
      });

      // The outbound signal: core → CTA row, gold, with a long tail.
      if (!reduced && signalEnd && intro === 1 && exit < 0.2) {
        if (!signal && now - lastSignal > SIGNAL_EVERY) {
          lastSignal = now;
          signal = { start: now };
        }
        if (signal) {
          const t = (now - signal.start) / SIGNAL_MS;
          const q0 = target;
          const q1 = { x: target.x - 220, y: target.y + 30 };
          const q2 = { x: signalEnd.x + 200, y: signalEnd.y };
          const q3 = signalEnd;
          const [r, g, b] = gold;
          for (let k = 12; k >= 0; k--) {
            const tt = Math.min(1, Math.max(0, t - k * 0.018));
            const e = 1 - (1 - tt) * (1 - tt); // ease-out
            const pos = bez(e, q0, q1, q2, q3);
            const a = ((12 - k + 1) / 13) * (k === 0 ? 1 : 0.55) * fade;
            const s = k === 0 ? 4.5 : 3 * (1 - k / 14);
            if (k === 0) {
              const glow = ctx.createRadialGradient(
                pos.x, pos.y, 0, pos.x, pos.y, 14
              );
              glow.addColorStop(0, `rgba(${r},${g},${b},${0.55 * fade})`);
              glow.addColorStop(1, `rgba(${r},${g},${b},0)`);
              ctx.fillStyle = glow;
              ctx.beginPath();
              ctx.arc(pos.x, pos.y, 14, 0, Math.PI * 2);
              ctx.fill();
            }
            ctx.fillStyle = `rgba(${r},${g},${b},${a})`;
            ctx.fillRect(pos.x - s / 2, pos.y - s / 2, s, s);
          }
          if (t >= 1.25) {
            signal = null;
            flashCta();
          }
        }
      }

      // Charge ebbs back toward rest.
      charge *= Math.exp(-dt / 1400);
      writeCharge();
    };

    const loop = (now) => {
      raf = 0;
      if (!running) return;
      render(now);
      raf = requestAnimationFrame(loop);
    };

    const setRunning = () => {
      running = visible && !document.hidden && !reduced && !!target;
      if (running && !raf) {
        lastT = 0;
        raf = requestAnimationFrame(loop);
      }
    };

    // The robot is lazy-loaded; wait for it before laying out.
    let tries = 0;
    let waitTimer = 0;
    const init = () => {
      if (layout()) {
        born = performance.now();
        lastSignal = born; // first signal ~6s after arrival, not at once
        if (reduced) render(born);
        setRunning();
      } else if (tries++ < 40) {
        waitTimer = setTimeout(init, 150);
      }
    };

    const io = new IntersectionObserver(([e]) => {
      visible = e.isIntersecting;
      setRunning();
    });
    io.observe(hero);

    const onVis = () => setRunning();
    document.addEventListener("visibilitychange", onVis);

    const ro = new ResizeObserver(() => {
      if (layout() && reduced) render(performance.now());
    });
    ro.observe(hero);

    const onMove = (e) => {
      const h = hero.getBoundingClientRect();
      mouse = { x: e.clientX - h.left, y: e.clientY - h.top };
      pointerIn = true;
    };
    const onLeave = () => {
      pointerIn = false;
    };
    const onClick = (e) => {
      const h = hero.getBoundingClientRect();
      explosions.push({
        x: e.clientX - h.left,
        y: e.clientY - h.top,
        radius: 0,
        life: 1,
      });
    };
    hero.addEventListener("mousemove", onMove, { passive: true });
    hero.addEventListener("mouseleave", onLeave);
    hero.addEventListener("click", onClick);

    init();

    return () => {
      running = false;
      if (raf) cancelAnimationFrame(raf);
      clearTimeout(waitTimer);
      io.disconnect();
      ro.disconnect();
      document.removeEventListener("visibilitychange", onVis);
      hero.removeEventListener("mousemove", onMove);
      hero.removeEventListener("mouseleave", onLeave);
      hero.removeEventListener("click", onClick);
      // Hand the robot and its pad back to their stylesheet.
      if (robotEl) robotEl.style.filter = "";
      if (padEl) padEl.style.opacity = "";
    };
  }, [theme?.name, theme?.accentColor]);

  return <canvas className="hv-flow" ref={canvasRef} aria-hidden="true" />;
}
